from itertools import combinations
from typing import Dict, Set, Tuple

Graph = Tuple[int, Dict[int, Set[int]]]

def common_neighborhood(g: Graph, s) -> Set[int]:
    n, adj = g
    s = list(s)
    if not s:
        return set(range(n))
    result = set(range(n))
    for u in s:
        result &= adj[u]
    return result

def count_Kab_copies(g: Graph, a: int, b: int) -> int:
    """Count labelled copies (A, B) of K_{a,b}: disjoint vertex sets of sizes a
    and b with every A-B edge present."""
    n, _ = g
    total = 0
    for A in combinations(range(n), a):
        candidates = common_neighborhood(g, A) - set(A)
        for _B in combinations(sorted(candidates), b):
            total += 1
    return total

if __name__ == "__main__":
    # K_{3,3} on vertices {0,1,2} x {3,4,5}
    adj = {v: set() for v in range(6)}
    for u in (0, 1, 2):
        for v in (3, 4, 5):
            adj[u].add(v); adj[v].add(u)
    g = (6, adj)
    print("copies of K_{3,3}:", count_Kab_copies(g, 3, 3))  # 1 (labelled)

from itertools import combinations
from math import comb
from typing import Dict, Set, Tuple
import random

Graph = Tuple[int, Dict[int, Set[int]]]

def common_neighborhood(g: Graph, s) -> Set[int]:
    n, adj = g
    result = set(range(n))
    for u in s:
        result &= adj[u]
    return result

def count_Kab_copies(g: Graph, a: int, b: int) -> int:
    n, _ = g
    total = 0
    for A in combinations(range(n), a):
        cand = common_neighborhood(g, A) - set(A)
        for _B in combinations(sorted(cand), b):
            total += 1
    return total

def random_K3t_free_graph(n: int, t: int, seed: int = 0) -> Graph:
    rng = random.Random(seed)
    adj: Dict[int, Set[int]] = {v: set() for v in range(n)}
    g = (n, adj)
    edges = list(combinations(range(n), 2)); rng.shuffle(edges)
    for u, v in edges:
        adj[u].add(v); adj[v].add(u)
        ok = all(len(common_neighborhood(g, tr)) <= t - 1
                 for tr in combinations(range(n), 3) if u in tr or v in tr)
        if not ok:
            adj[u].discard(v); adj[v].discard(u)
    return g

def verify_bound(a: int, b: int, n: int, seed: int = 0) -> bool:
    """Check #copies of K_{a,b} <= C(b,a-3) * n^3 in a random K_{3,b+1}-free graph."""
    g = random_K3t_free_graph(n, b + 1, seed)
    return count_Kab_copies(g, a, b) <= comb(b, a - 3) * n ** 3

if __name__ == "__main__":
    for n in range(6, 13):
        print(n, verify_bound(3, 3, n, seed=n))

from math import comb

def copy_density_bound(a: int, b: int, n: int) -> float:
    """Upper bound on the copy density #copies / n^(a+b), namely C(b,a-3)/n^(a+b-3),
    which tends to 0 since a+b-3 >= 3 > 0 for 3 <= a <= b."""
    return comb(b, a - 3) / n ** (a + b - 3)

if __name__ == "__main__":
    a, b = 3, 3
    for n in (10, 20, 50, 100, 1000):
        print(f"n={n:5d}  density bound = {copy_density_bound(a, b, n):.3e}")

