function TuranUpperBound(a, b, n):
    require 3 <= a <= b
    t <- b + 1                      # forbidden graph is K_{3,t}
    cap <- t - 1                    # every triple has <= cap common neighbors
    per_triple <- C(cap, b) * C(cap, a - 3)   # fiber bound; C(b,b)=1
    num_triples <- C(n, 3)
    tight <- num_triples * per_triple
    loose <- C(b, a - 3) * n^3      # since C(n,3) <= n^3 and cap = b
    return (tight, loose)

function IsK3tFree(G, t):
    for each triple {x, y, z} of vertices:
        common <- N(x) INTERSECT N(y) INTERSECT N(z)
        if |common| >= t:
            return False        # (x,y,z) with t common nbrs => K_{3,t}
    return True

