    for u in (0, 1, 2):
        for v in (3, 4, 5):
            adj[u].add(v); adj[v].add(u)
    g = (6, adj)
    print(is_K3t_free(g, 3))  # False (it is a K_{3,3})
    print(is_K3t_free(g, 4))  # True

